// items[0] = semana atual, items[1] = semana anterior
const items = $input.all();
const currentRows = (items[0] && items[0].json && items[0].json.rows) ? items[0].json.rows : [];
const prevRows = (items[1] && items[1].json && items[1].json.rows) ? items[1].json.rows : [];

var clicks = 0, impressions = 0;
currentRows.forEach(function(r) { clicks += r.clicks; impressions += r.impressions; });

var clicksPrev = 0, impressionsPrev = 0;
prevRows.forEach(function(r) { clicksPrev += r.clicks; impressionsPrev += r.impressions; });

function delta(curr, prev) {
  if (prev === 0) return curr > 0 ? '+100% ↑' : '—';
  var pct = Math.round((curr - prev) / prev * 100);
  return pct >= 0 ? '+' + pct + '% ↑' : pct + '% ↓';
}

var ctr = impressions > 0 ? ((clicks / impressions) * 100).toFixed(1) : '0';
var avgPos = currentRows.length > 0
  ? (currentRows.reduce(function(s, r) { return s + r.position; }, 0) / currentRows.length).toFixed(1)
  : '0';

var top10 = currentRows.slice().sort(function(a, b) { return b.clicks - a.clicks; }).slice(0, 10)
  .map(function(r, i) {
    var q = r.keys[0].substring(0, 38);
    var ctrQ = (r.ctr * 100).toFixed(0);
    return (i+1) + '. "' + q + '" — ' + r.clicks + 'clq | pos.' + r.position.toFixed(1) + ' | CTR ' + ctrQ + '%';
  });

return [{
  json: {
    gsc_totalClicks: clicks,
    gsc_totalImpressions: impressions,
    gsc_ctr: ctr + '%',
    gsc_avgPosition: avgPos,
    gsc_delta_clicks: delta(clicks, clicksPrev),
    gsc_delta_impressions: delta(impressions, impressionsPrev),
    gsc_top10Queries: top10.join('\n'),
    gsc_periodo: $now.minus({ days: 7 }).toFormat('dd/MM') + ' a ' + $now.minus({ days: 1 }).toFormat('dd/MM/yyyy')
  }
}];

